use stable.herd;
use stable.ledger;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    var output = "";
    var first = true;

    for pony in herd.lineup() {
        let fed = herd.feed(pony: pony, scoops: 3);
        if first {
            output = ledger.render(fed);
            first = false;
        } else {
            output = output.concat(other: ",").concat(other: ledger.render(fed));
        }
    }

    io.write(text: output)?;
    return Ok(unit);
}

use stable.herd.{lineup, feed};
use stable.ledger.{render};

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let ponies = lineup();
    var output = "";
    var i = 0;

    while i < ponies.len() {
        let pony = ponies.get(index: i);
        let fed = feed(pony: pony, scoops: 3);
        if i == 0 {
            output = render(fed);
        } else {
            output = output.concat(other: ",").concat(other: render(fed));
        }
        i = i + 1;
    }

    io.write(text: output)?;
    return Ok(unit);
}

