use harbor.signal;

fn entries() -> String {
    let signals = signal.today();
    var rendered = "";
    var index = 0;
    while index < signals.length() {
        let entry = match signals.at(index: index) {
            Calm => "calm",
            Gale(speed) => "gale:".concat(other: speed.to_text()),
            Fog(density) => "fog:".concat(other: density),
        };
        if index > 0 {
            rendered = rendered.concat(other: ";");
        }
        rendered = rendered.concat(other: entry);
        index = index + 1;
    }
    rendered
}

