use relay.feed;

fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    var total = 0;
    for frame in relay.feed.frames() {
        let value = match relay.feed.decode(frame: frame) {
            Ok(value) => value,
            Err(_) => 0,
        };
        total = total + value;
    }
    relay.feed.emit(io: io, total: total)?;
    return Ok(unit);
}

use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
