    var total = 0;
    var i = 0;
    while i < frames.len() {
        let value = match relay.feed.decode(frame: frames.get(index: i)) {
            Ok(value) => value,
            Err(_) => 0,
        };
        total = total + value;
        i = i + 1;
    }
    relay.feed.emit(io: io, total: total)?;
    return Ok(unit);
}

use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let frames = relay.feed.frames();
    var total = 0;
    var i = 0;
    while i < frames.len() {
        let value = match frames.get(index: i) {
            Some(frame) => match relay.feed.decode(frame: frame) {
                Ok(value) => value,
                Err(_) => 0,
            },
            None => 0,
        };
        total = total + value;
        i = i + 1;
    }
    relay.feed.emit(io: io, total: total)?;
    return Ok(unit);
}

use galley.menu;
use galley.kitchen;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let board = menu.board();
    var first = true;

    for dish in board {
        if !first {
            io.write(text: ";")?;
        }
        kitchen.serve(io: io, dish: dish)?;
        first = false;
    }

    return Ok(unit);
}

